def shortestPalindromeLength(s):
    n = len(s)
    t = s + '#' + s[::-1]
    pi = [0] * len(t)
    for i in range(1, len(t)):
        k = pi[i - 1]
        while k and t[i] != t[k]:
            k = pi[k - 1]
        if t[i] == t[k]:
            k += 1
        pi[i] = k
    return 2 * n - pi[-1]
